// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1200, 420);

var W = 1200, H = 420;
var axisY = 200;
var x1 = 360;
var leftX = 35;
var rightX = 1172;
var focalScale = 58;
var f1 = 8;
var f2 = 2;
var thetaIn = 0.06;
var lens2Offset = 0;
var currentStep = 0;

var purple = '#cf6df4';
var blue = '#0b43ff';
var black = '#000000';

var scene = draw.group();

var arrowBlack = draw.marker(9, 9, function (add) {
  add.path('M 0 0 L 9 4.5 L 0 9 z').fill(black);
}).ref(8.4, 4.5).attr({ orient: 'auto', markerUnits: 'strokeWidth' });

var arrowBlue = draw.marker(9, 9, function (add) {
  add.path('M 0 0 L 9 4.5 L 0 9 z').fill(blue);
}).ref(8.4, 4.5).attr({ orient: 'auto', markerUnits: 'strokeWidth' });

function clamp(v, a, b) {
  return Math.max(a, Math.min(b, v));
}

function fmt(v, n) {
  return Number(v).toFixed(n == null ? 2 : n);
}

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

function line(g, xA, yA, xB, yB, color, width, dash) {
  var el = g.line(xA, yA, xB, yB).stroke({ color: color, width: width, linecap: 'round', linejoin: 'round' });
  if (dash) el.attr('stroke-dasharray', dash);
  return el;
}

function haloText(g, txt, x, y, size, color, anchor, family) {
  return g.text(txt)
    .font({ family: family || 'serif', size: size, anchor: anchor || 'middle' })
    .fill(color || black)
    .attr({
      x: x,
      y: y,
      'dominant-baseline': 'middle',
      'paint-order': 'stroke',
      stroke: '#ffffff',
      'stroke-width': Math.max(2, size * 0.11),
      'stroke-linejoin': 'round'
    });
}

function arcPath(cx, cy, r, a0, a1) {
  var xA = cx + r * Math.cos(a0), yA = cy + r * Math.sin(a0);
  var xB = cx + r * Math.cos(a1), yB = cy + r * Math.sin(a1);
  var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
  var sweep = a1 >= a0 ? 1 : 0;
  return 'M ' + xA + ' ' + yA + ' A ' + r + ' ' + r + ' 0 ' + large + ' ' + sweep + ' ' + xB + ' ' + yB;
}

function drawBracket(g, xA, xB, y, label, tip) {
  var bg = g.group();
  line(bg, xA, y, xB, y, black, 2.2);
  line(bg, xA, y - 8, xA, y + 8, black, 2.2);
  line(bg, xB, y - 8, xB, y + 8, black, 2.2);
  haloText(bg, label, (xA + xB) / 2, y - 23, 25, black, 'middle');
  bg.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(label, tip);
    });
  return bg;
}

function thinLensPathConvex(x, h, w) {
  var top = axisY - h, bot = axisY + h;
  return 'M ' + x + ' ' + top +
    ' C ' + (x + w) + ' ' + (axisY - h * 0.55) + ' ' + (x + w) + ' ' + (axisY + h * 0.55) + ' ' + x + ' ' + bot +
    ' C ' + (x - w) + ' ' + (axisY + h * 0.55) + ' ' + (x - w) + ' ' + (axisY - h * 0.55) + ' ' + x + ' ' + top + ' Z';
}

function thinLensPathConcave(x, h, w) {
  var top = axisY - h, bot = axisY + h;
  return 'M ' + (x - w) + ' ' + top +
    ' C ' + (x + w * 0.38) + ' ' + (axisY - h * 0.48) + ' ' + (x + w * 0.38) + ' ' + (axisY + h * 0.48) + ' ' + (x - w) + ' ' + bot +
    ' L ' + (x + w) + ' ' + bot +
    ' C ' + (x - w * 0.38) + ' ' + (axisY + h * 0.48) + ' ' + (x - w * 0.38) + ' ' + (axisY - h * 0.48) + ' ' + (x + w) + ' ' + top + ' Z';
}

function beamState(slopes, x2, hits) {
  var sepLens = Math.abs(hits[0] - hits[1]);
  var yRa = hits[0] + slopes[0] * (rightX - x2);
  var yRb = hits[1] + slopes[1] * (rightX - x2);
  var sepRight = Math.abs(yRa - yRb);
  if (Math.abs(slopes[0] - slopes[1]) < 0.004) return 'parallel';
  return sepRight < sepLens ? 'converging' : 'diverging';
}

function redraw() {
  scene.clear();

  var xF = x1 + f1 * focalScale;
  var yF = axisY + f1 * focalScale * Math.tan(thetaIn);
  var afocalX2 = xF - f2 * focalScale;
  var x2 = afocalX2 + lens2Offset;
  x2 = clamp(x2, 70, W - 150);
  var actualOffset = x2 - afocalX2;
  lens2Offset = actualOffset;

  var f2Pixels = f2 * focalScale;
  var rays = [
    { hit: axisY - 72, width: 5.2, alpha: 1 },
    { hit: axisY - 15, width: 1.4, alpha: 0.88 }
  ];

  var gAxis = scene.group();
  line(gAxis, 15, axisY, W - 15, axisY, blue, 1.1);
  gAxis.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Optical axis: the zero-angle reference for δi and δo.', e); })
    .on('mouseleave', hideTooltip);

  var gRays = scene.group();
  var slopesOut = [];
  var hitsAtLens2 = [];

  for (var i = 0; i < rays.length; i++) {
    var yAtLens1 = rays[i].hit;
    var yLeft = yAtLens1 - Math.tan(thetaIn) * (x1 - leftX);
    var yAtLens2 = yAtLens1 + (yF - yAtLens1) * ((x2 - x1) / (xF - x1));
    var mBefore2 = (yF - yAtLens2) / (xF - x2);
    var mAfter2 = mBefore2 + (yAtLens2 - axisY) / f2Pixels;
    var yRight = yAtLens2 + mAfter2 * (rightX - x2);

    hitsAtLens2.push(yAtLens2);
    slopesOut.push(mAfter2);

    line(gRays, leftX, yLeft, x1, yAtLens1, purple, rays[i].width, null).opacity(rays[i].alpha);
    line(gRays, x1, yAtLens1, x2, yAtLens2, purple, rays[i].width, null).opacity(rays[i].alpha);
    line(gRays, x2, yAtLens2, rightX, yRight, purple, rays[i].width, null).opacity(rays[i].alpha);
  }

  line(gRays, x2, hitsAtLens2[0], xF, yF, purple, 2.3, '3,5').opacity(0.9);

  gRays.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('Purple rays: lens 1 aims the incoming parallel bundle at the shared focal point; lens 2 turns that offset into the outgoing angle.', e);
    })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Ray construction', 'The objective converts the incoming angle into the transverse offset d at its focal plane. In the afocal position, the negative eyepiece makes the rays parallel again, but at the larger angle set by f1/f2.');
    });

  var gMeasure = scene.group();
  line(gMeasure, xF, axisY, xF, yF, blue, 2.1).marker('end', arrowBlue);
  gMeasure.circle(11).center(xF, axisY).fill(blue);
  gMeasure.circle(12).center(xF, yF).fill(purple).stroke({ color: '#9b2fe0', width: 1.3 });
  haloText(gMeasure, 'd', xF + 22, (axisY + yF) / 2, 24, black, 'start');
  gMeasure.css('cursor', 'ns-resize')
    .on('mousemove', function (e) { showTooltip('Drag this focal-plane offset: changing d changes the incoming angle and the outgoing angle together.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Focal-plane offset d', 'For a small incoming angle, lens 1 forms an off-axis focal point with d ≈ f1δi. Lens 2 converts that same d back into an outgoing angle δo ≈ d/f2.');
    });

  var dragAngle = false;
  gMeasure.on('mousedown', function (e) {
    dragAngle = true;
    e.preventDefault();
  });
  document.addEventListener('mousemove', angleMove);
  document.addEventListener('mouseup', angleUp);

  function angleMove(e) {
    if (!dragAngle) return;
    var p = svgPoint(e);
    var maxD = 78, minD = -50;
    var d = clamp(p.y - axisY, minD, maxD);
    thetaIn = Math.atan(d / (f1 * focalScale));
    redraw();
  }
  function angleUp() {
    dragAngle = false;
    document.removeEventListener('mousemove', angleMove);
    document.removeEventListener('mouseup', angleUp);
  }

  var gLenses = scene.group();
  var lens1 = gLenses.path(thinLensPathConvex(x1, 170, 16)).fill('#ffffff').stroke({ color: black, width: 3.4, linejoin: 'round' });
  var lens2 = gLenses.path(thinLensPathConcave(x2, 108, 15)).fill('#ffffff').stroke({ color: black, width: 3.4, linejoin: 'round' });

  var lens1Hot = gLenses.rect(54, 360).center(x1, axisY).fill({ color: '#fff', opacity: 0.001 });
  lens1Hot.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Lens 1: positive objective lens with focal length f1.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Lens 1', 'The objective lens focuses each incoming parallel direction to a point in its focal plane. A longer f1 makes the same input angle produce a larger offset d.');
    });

  var lens2Hot = gLenses.rect(62, 250).center(x2, axisY).fill({ color: '#fff', opacity: 0.001 });
  lens2Hot.css('cursor', 'ew-resize')
    .on('mousemove', function (e) { showTooltip('Drag lens 2 horizontally. Only the shared-focal-point position gives parallel output rays.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Lens 2', 'The Galilean eyepiece is a negative lens. When its focal point coincides with the objective focal point, the exiting rays are parallel; shifting it breaks the afocal condition.');
    });

  var draggingLens = false;
  lens2Hot.on('mousedown', function (e) {
    draggingLens = true;
    e.preventDefault();
  });
  document.addEventListener('mousemove', lensMove);
  document.addEventListener('mouseup', lensUp);

  function lensMove(e) {
    if (!draggingLens) return;
    var p = svgPoint(e);
    lens2Offset = clamp(p.x - afocalX2, -170, 170);
    redraw();
  }
  function lensUp() {
    draggingLens = false;
    document.removeEventListener('mousemove', lensMove);
    document.removeEventListener('mouseup', lensUp);
  }

  var gAngles = scene.group();
  for (var j = 0; j < 2; j++) {
    var baseY = rays[j].hit - Math.tan(thetaIn) * (x1 - 72);
    line(gAngles, 46, baseY, 145, baseY, blue, 0.9);
    var aIn = Math.atan(Math.tan(thetaIn));
    var arcIn = gAngles.path(arcPath(72, baseY, 18, 0, aIn))
      .fill('none').stroke({ color: black, width: 2.1, linecap: 'round' })
      .marker('end', arrowBlack);
    haloText(gAngles, 'δᵢ', 24, baseY - 14, 23, black, 'middle');
  }

  var meanOut = (slopesOut[0] + slopesOut[1]) / 2;
  var outAngle = Math.atan(meanOut);
  gAngles.path(arcPath(1045, axisY + 6, 45, 0, outAngle))
    .fill('none').stroke({ color: black, width: 2.4, linecap: 'round' })
    .marker('end', arrowBlack);
  haloText(gAngles, 'δₒ', 1110, axisY + 32, 26, black, 'middle');

  var gBrackets = scene.group();
  drawBracket(gBrackets, x1, xF, 392, 'f₁', 'Objective focal length: lens 1 maps angle δi to offset d.');
  drawBracket(gBrackets, x2, xF, 340, 'f₂', 'Eyepiece focal length: lens 2 maps offset d to outgoing angle δo.');

  var gLabels = scene.group();
  haloText(gLabels, 'lens 1', x1 + 6, 28, 30, blue, 'middle');
