  return 'M ' + (x - w) + ' ' + top +
    ' C ' + (x + w * 0.42) + ' ' + (axisY - h * 0.47) + ' ' + (x + w * 0.42) + ' ' + (axisY + h * 0.47) + ' ' + (x - w) + ' ' + bot +
    ' L ' + (x + w) + ' ' + bot +
    ' C ' + (x - w * 0.42) + ' ' + (axisY + h * 0.47) + ' ' + (x - w * 0.42) + ' ' + (axisY - h * 0.47) + ' ' + (x + w) + ' ' + top + ' Z';
}

function beamState(slopes, x2, hits) {
  var sepLens = Math.abs(hits[0] - hits[1]);
  var yRa = hits[0] + slopes[0] * (rightX - x2);
  var yRb = hits[1] + slopes[1] * (rightX - x2);
  var sepRight = Math.abs(yRa - yRb);
  if (Math.abs(slopes[0] - slopes[1]) < 0.004) return 'parallel';
  return sepRight < sepLens ? 'converging' : 'diverging';
}

var draggingAngle = false;
var draggingLens = false;
var lastAfocalX2 = 0;

document.addEventListener('mousemove', function (e) {
  if (draggingAngle) {
    var p = svgPoint(e);
    var d = clamp(p.y - axisY, -70, 110);
    thetaIn = Math.atan(d / (f1 * focalScale));
    redraw();
  } else if (draggingLens) {
    var q = svgPoint(e);
    lens2Offset = clamp(q.x - lastAfocalX2, -210, 210);
    redraw();
  }
});

document.addEventListener('mouseup', function () {
  draggingAngle = false;
  draggingLens = false;
});

function redraw() {
  scene.clear();

  var xF = x1 + f1 * focalScale;
  var yF = axisY + f1 * focalScale * Math.tan(thetaIn);
  var afocalX2 = xF - f2 * focalScale;
  lastAfocalX2 = afocalX2;
  var x2 = clamp(afocalX2 + lens2Offset, 105, W - 180);
  lens2Offset = x2 - afocalX2;
  var f2Pixels = f2 * focalScale;

  var rays = [
    { hit: axisY - 96, width: 8.2, alpha: 1 },
    { hit: axisY - 18, width: 2.1, alpha: 0.9 }
  ];

  var gAxis = scene.group();
  line(gAxis, 18, axisY, W - 18, axisY, blue, 1.6);
  gAxis.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Optical axis: the zero-angle reference for δi and δo.', e); })
    .on('mouseleave', hideTooltip);

  var gRays = scene.group();
  var slopesOut = [];
  var hitsAtLens2 = [];

  for (var i = 0; i < rays.length; i++) {
    var yAtLens1 = rays[i].hit;
    var yLeft = yAtLens1 - Math.tan(thetaIn) * (x1 - leftX);
    var yAtLens2 = yAtLens1 + (yF - yAtLens1) * ((x2 - x1) / (xF - x1));
    var mBefore2 = (yF - yAtLens2) / (xF - x2);
    var mAfter2 = mBefore2 + (yAtLens2 - axisY) / f2Pixels;
    var yRight = yAtLens2 + mAfter2 * (rightX - x2);

    hitsAtLens2.push(yAtLens2);
    slopesOut.push(mAfter2);

    line(gRays, leftX, yLeft, x1, yAtLens1, purple, rays[i].width).opacity(rays[i].alpha);
    line(gRays, x1, yAtLens1, x2, yAtLens2, purple, rays[i].width).opacity(rays[i].alpha);
    line(gRays, x2, yAtLens2, rightX, yRight, purple, rays[i].width).opacity(rays[i].alpha);
  }

  line(gRays, x2, hitsAtLens2[0], xF, yF, purple, 3.6, '7,8').opacity(0.88);

  gRays.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('Purple rays: lens 1 aims the incoming parallel bundle at the shared focal point; lens 2 turns that offset into the outgoing angle.', e);
    })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Ray construction', 'The objective converts the incoming angle into the transverse offset d at its focal plane. In the afocal position, the negative eyepiece makes the rays parallel again, but at a larger angle set by f1/f2.');
    });

  var gLenses = scene.group();
  gLenses.path(thinLensPathConvex(x1, 230, 18)).fill('#ffffff').stroke({ color: black, width: 4.5, linejoin: 'round' });
  gLenses.path(thinLensPathConcave(x2, 142, 19)).fill('#ffffff').stroke({ color: black, width: 4.5, linejoin: 'round' });

  var lens1Hot = gLenses.rect(72, 500).center(x1, axisY).fill({ color: '#fff', opacity: 0.001 });
  lens1Hot.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Lens 1: positive objective lens with focal length f1.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Lens 1', 'The objective lens focuses each incoming parallel direction to a point in its focal plane. A longer f1 makes the same input angle produce a larger offset d.');
    });

  var lens2Hot = gLenses.rect(82, 330).center(x2, axisY).fill({ color: '#fff', opacity: 0.001 });
  lens2Hot.css('cursor', 'ew-resize')
    .on('mousemove', function (e) { showTooltip('Drag lens 2 horizontally. Only the shared-focal-point position gives parallel output rays.', e); })
    .on('mouseleave', hideTooltip)
    .on('mousedown', function (e) {
      draggingLens = true;
      e.preventDefault();
    })
    .on('click', function () {
      showPopup('Lens 2', 'The Galilean eyepiece is a negative lens. When its focal point coincides with the objective focal point, the exiting rays are parallel; shifting it breaks the afocal condition.');
    });

  var gMeasure = scene.group();
  var arrowEndY = yF;
  line(gMeasure, xF, axisY + (yF >= axisY ? 12 : -12), xF, arrowEndY, black, 5.2).marker('end', arrowBlack);
  gMeasure.circle(16).center(xF, axisY).fill(blue);
  gMeasure.circle(6).center(xF, yF).fill(purple).opacity(0.45);
  haloText(gMeasure, 'd', xF + 28, (axisY + yF) / 2, 38, black, 'start');
  var dHotH = Math.max(54, Math.abs(yF - axisY) + 42);
  gMeasure.rect(58, dHotH).center(xF, (axisY + yF) / 2).fill({ color: '#fff', opacity: 0.001 })
    .css('cursor', 'ns-resize')
    .on('mousemove', function (e) { showTooltip('Drag the d marker: changing d changes the incoming angle and the outgoing angle together.', e); })
    .on('mouseleave', hideTooltip)
    .on('mousedown', function (e) {
      draggingAngle = true;
      e.preventDefault();
    })
    .on('click', function () {
      showPopup('Focal-plane offset d', 'For a small incoming angle, lens 1 forms an off-axis focal point with d ≈ f1δi. Lens 2 converts that same d back into an outgoing angle δo ≈ d/f2.');
    });

  var gAngles = scene.group();
  for (var j = 0; j < 2; j++) {
    var baseY = rays[j].hit - Math.tan(thetaIn) * (x1 - 92);
    line(gAngles, 45, baseY, 160, baseY, blue, 1.2);
    gAngles.path(arcPath(95, baseY, 26, 0, Math.atan(Math.tan(thetaIn))))
      .fill('none')
      .stroke({ color: black, width: 3.1, linecap: 'round' })
      .marker('end', arrowBlack);
    haloText(gAngles, 'δᵢ', 29, baseY - 24, 41, black, 'middle');
  }

  var meanOut = (slopesOut[0] + slopesOut[1]) / 2;
  var outAngle = Math.atan(meanOut);
  var arcCx = 1280;
  var arcCy = axisY + 10;
  gAngles.path(arcPath(arcCx, arcCy, 64, 0, outAngle))
    .fill('none')
    .stroke({ color: black, width: 3.5, linecap: 'round' })
    .marker('end', arrowBlack);
  haloText(gAngles, 'δₒ', 1358, axisY + 47, 48, black, 'middle');

  var gBrackets = scene.group();
  drawBracket(gBrackets, x1, xF, 512, 'f₁', 'Objective focal length: lens 1 maps angle δi to offset d.', -43);
  drawBracket(gBrackets, x2, xF, 445, 'f₂', 'Eyepiece focal length: lens 2 maps offset d to outgoing angle δo.', -37);

  var gLabels = scene.group();
  haloText(gLabels, 'lens 1', x1 + 10, 41, 55, blue, 'middle');
  haloText(gLabels, 'lens 2', x2 + 8, 115, 55, blue, 'middle');

  var afocalGood = Math.abs(lens2Offset) < 1.5 && f2 < f1;
  var state = afocalGood ? 'parallel' : beamState(slopesOut, x2, hitsAtLens2);
  var mag = f1 / f2;
  var dPhysical = f1 * Math.tan(thetaIn);
  var deltaInDeg = Math.abs(thetaIn * 180 / Math.PI);
  var deltaOutDeg = Math.abs(Math.atan(meanOut) * 180 / Math.PI);

  var magEl = document.getElementById('magReadout');
  var offEl = document.getElementById('offsetReadout');
  var beamEl = document.getElementById('beamReadout');
  if (magEl) magEl.textContent = fmt(mag, 2) + '×';
  if (offEl) offEl.textContent = fmt(dPhysical, 2) + ' units';
  if (beamEl) {
    var msg = 'Exit beam: ' + state;
    if (!afocalGood) msg += ' (lens 2 shifted ' + fmt(lens2Offset / focalScale, 2) + ' focal-length units from afocal)';
    if (f2 >= f1) msg = 'Warning: f2 ≥ f1, so a right-side Galilean afocal placement is not possible.';
    msg += ' · |δi|≈' + fmt(deltaInDeg, 1) + '°, |δo|≈' + fmt(deltaOutDeg, 1) + '°';
    beamEl.textContent = msg;
    beamEl.style.color = afocalGood ? blue : '#b15a00';
  }
}

function update_objectiveFocalLength(v) {
  f1 = v;
  lens2Offset = 0;
  redraw();
}

function update_eyepieceFocalLength(v) {
  f2 = v;
  lens2Offset = 0;
  redraw();
}

var demoSteps = [
  {
    title: 'Afocal telescope setup',
    narration: 'Lens 2 is positioned so the focal point of lens 1 coincides with the focal point of lens 2. The incoming parallel bundle exits as another parallel bundle, but at a larger angle.',
    state: { objectiveFocalLength: 8, eyepieceFocalLength: 2 }
  },
  {
    title: 'Magnification from focal-length ratio',
    narration: 'With f1 = 8 and f2 = 2, the angular magnification readout shows δo/δi = 4. The telescope multiplies angles without needing the rays to form a final real image in the diagram.',
    state: { objectiveFocalLength: 8, eyepieceFocalLength: 2 }
  },
  {
    title: 'Lengthen the objective',
    narration: 'Increasing f1 moves the shared focal point farther from lens 1 and increases the offset d for the same incoming angle. The outgoing angle grows because the focal-length ratio f1/f2 grows.',
    state: { objectiveFocalLength: 11, eyepieceFocalLength: 2 }
  },
  {
    title: 'Shorten the eyepiece',
    narration: 'Reducing f2 makes lens 2 convert the same focal offset into an even larger outgoing angle. The lens separation adjusts to maintain the Galilean afocal condition f1 - f2.',
    state: { objectiveFocalLength: 8, eyepieceFocalLength: 1.5 }
  },
  {
    title: 'Break the afocal condition',
    narration: 'Now drag lens 2 along the optical axis. When it is not at the afocal separation, the outgoing rays are no longer parallel, showing why the focal points must align.',
    state: { objectiveFocalLength: 8, eyepieceFocalLength: 2 }
  }
];

function applyStep(idx) {
  currentStep = clamp(idx, 0, demoSteps.length - 1);
  var st = demoSteps[currentStep];

  var n = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (n) n.textContent = st.title + ': ' + st.narration;
  if (lab) lab.textContent = (currentStep + 1) + '/' + demoSteps.length;

  var f1Input = document.getElementById('objectiveFocalLengthInput');
  var f1Val = document.getElementById('objectiveFocalLengthVal');
  var f2Input = document.getElementById('eyepieceFocalLengthInput');
  var f2Val = document.getElementById('eyepieceFocalLengthVal');

  if (f1Input) f1Input.value = st.state.objectiveFocalLength;
  if (f1Val) f1Val.value = st.state.objectiveFocalLength;
  f1 = +st.state.objectiveFocalLength;

  if (f2Input) f2Input.value = st.state.eyepieceFocalLength;
  if (f2Val) f2Val.value = st.state.eyepieceFocalLength;
  f2 = +st.state.eyepieceFocalLength;

  lens2Offset = currentStep === 4 ? 86 : 0;
  redraw();
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A Galilean two-lens telescope converts a small incoming ray angle into a larger outgoing parallel ray angle, with angular magnification set by the focal-length ratio f1/f2 when the lenses are in the afocal separation.
KEY INSIGHT (what students should walk away understanding): The telescope magnifies angles because lens 1 converts the incoming angle into a focal-plane offset, and lens 2 converts that same offset back into a larger outgoing angle set by f1/f2.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "A Galilean two-lens telescope converts a small incoming ray angle into a larger outgoing parallel ray angle, with angular magnification set by the focal-length ratio f1/f2 when the lenses are in the afocal separation.",
  "figureType": "diagram",
  "elements": [
    "horizontal optical axis drawn as a thin blue line",
    "convex objective lens on the left, labeled 'lens 1'",
    "concave eyepiece lens on the right, labeled 'lens 2'",
    "two incoming parallel purple rays entering from the left at angle δi to the optical axis",
    "curved angle markers at the left showing δi for the incoming ray direction",
    "purple ray segments refracted by lens 1 toward the shared off-axis focal point",
    "purple ray segments passing through lens 2 and emerging to the right",
    "two outgoing parallel purple rays leaving at a larger angle δo to the optical axis in the afocal case",
    "curved angle marker at the right showing δo for the outgoing ray direction",
    "dotted purple construction ray showing the would-be continuation toward the shared focal point",
    "blue vertical offset marker d from the optical axis to the off-axis focal point",
    "blue point on the optical axis above the offset marker",
    "purple point or ray intersection marking the off-axis focal point",
    "horizontal bracket labeled f1 from lens 1 to the shared focal point position",
    "horizontal bracket labeled f2 from lens 2 to the shared focal point position",
    "real-time readout of angular magnification δo/δi = f1/f2",
    "warning/readout for non-afocal lens 2 positions showing converging, parallel, or diverging exit beam"
  ],
  "interactions": [
    {
      "id": "objectiveFocalLength",
      "type": "slider",
      "label": "Objective focal length f1",
      "range": [
        4,
        12,
        0.5
      ],
      "default": 8,
      "teaches": "A longer objective focal length increases angular magnification because the same incoming angle creates a larger off-axis focal displacement before the eyepiece"
    },
    {
      "id": "eyepieceFocalLength",
      "type": "slider",
      "label": "Eyepiece focal length f2",
      "range": [
        1,
        5,
        0.25
      ],
      "default": 2,
      "teaches": "A shorter eyepiece focal length increases angular magnification because it turns the same focal-plane offset into a steeper outgoing angle"
    },
    {
      "id": "inputAngleDrag",
      "type": "drag",
      "teaches": "Changing the incoming angle changes both the off-axis focal displacement d and the outgoing angle, while their ratio stays fixed by f1/f2 in the afocal configuration"
    },
    {
      "id": "eyepiecePositionDrag",
      "type": "drag",
      "teaches": "Only when lens 2 is placed so its focal point coincides with the objective focal point do the exiting rays become parallel; moving it away makes the telescope no longer afocal"
    }
  ],
  "demo_steps": [
    {
      "title": "Afocal telescope setup",
      "narration": "Lens 2 is positioned so the focal point of lens 1 coincides with the focal point of lens 2. The incoming parallel bundle exits as another parallel bundle, but at a larger angle.",
      "state": {
        "objectiveFocalLength": 8,
        "eyepieceFocalLength": 2
      }
    },
    {
      "title": "Magnification from focal-length ratio",
      "narration": "With f1 = 8 and f2 = 2, the angular magnification readout shows δo/δi = 4. The telescope multiplies angles without needing the rays to form a final real image in the diagram.",
      "state": {
        "objectiveFocalLength": 8,
        "eyepieceFocalLength": 2
      }
    },
    {
      "title": "Lengthen the objective",
      "narration": "Increasing f1 moves the shared focal point farther from lens 1 and increases the offset d for the same incoming angle. The outgoing angle grows because the focal-length ratio f1/f2 grows.",
      "state": {
        "objectiveFocalLength": 11,
        "eyepieceFocalLength": 2
      }
    },
    {
      "title": "Shorten the eyepiece",
      "narration": "Reducing f2 makes lens 2 convert the same focal offset into an even larger outgoing angle. The lens separation adjusts to maintain the Galilean afocal condition f1 - f2.",
      "state": {
        "objectiveFocalLength": 8,
        "eyepieceFocalLength": 1.5
      }
    },
    {
      "title": "Break the afocal condition",
      "narration": "Now drag lens 2 along the optical axis. When it is not at the afocal separation, the outgoing rays are no longer parallel, showing why the focal points must align.",
      "state": {
        "objectiveFocalLength": 8,
        "eyepieceFocalLength": 2
      }
    }
  ],
  "keyInsight": "The telescope magnifies angles because lens 1 converts the incoming angle into a focal-plane offset, and lens 2 converts that same offset back into a larger outgoing angle set by f1/f2.",
  "reconstructionNotes": "Use a wide horizontal SVG layout. Place a tall black convex objective lens left of center and a shorter black concave eyepiece to its right. Draw the optical axis as a thin blue horizontal line. Draw two purple incoming rays from the left, parallel and slightly tilted; one ray may be thicker to emphasize the main construction ray. After lens 1, bend the rays toward an off-axis focal point to the right of lens 2, then through lens 2 so they exit parallel in the default afocal state. Show δi at the left with small curved arrows and δo at the right with a curved arrow. Use blue for the optical-axis reference and the vertical offset marker d, and purple for all light rays and construction rays. The f1 bracket should span from lens 1 to the shared focal point position; the f2 bracket should span from lens 2 to that same point. When f1 or f2 changes, keep lens 2 at the Galilean afocal separation by default and update the displayed magnification ratio. When lens 2 is dragged away from that position, visibly change the exiting rays from parallel to converging or diverging and update the focal-point alignment cue."
}

