    })
    .on('click', function () {
      showPopup('Lens 2', 'The eyepiece is a negative lens. At the afocal separation f1 − f2, the incoming converging bundle leaves as a parallel bundle; shifting the lens makes the exit beam converge or diverge.');
    });

  var gMeasure = scene.group();
  var dStart = axisY + (yF >= axisY ? 8 : -8);
  var dEnd = yF - (yF >= axisY ? 8 : -8);
  line(gMeasure, xF, dStart, xF, dEnd, black, 6).marker('end', arrowD);
  gMeasure.circle(28).center(xF, axisY).fill(blue);
  gMeasure.circle(12).center(xF, yF).fill(purple).opacity(0.58);
  haloText(gMeasure, 'd', xF + 36, (axisY + yF) / 2, 54, black, 'start');

  var dHotH = Math.max(72, Math.abs(yF - axisY) + 56);
  gMeasure.rect(88, dHotH).center(xF, (axisY + yF) / 2).fill({ color: '#fff', opacity: 0.001 })
    .css('cursor', 'ns-resize')
    .on('mousemove', function (e) { showTooltip('Drag this marker: d ≈ f1δi, so changing d changes the incoming and outgoing angles together.', e); })
    .on('mouseleave', hideTooltip)
    .on('mousedown', function (e) {
      draggingAngle = true;
      e.preventDefault();
    })
    .on('click', function () {
      showPopup('Focal-plane offset d', 'For small angles, the objective forms an off-axis focal point with d ≈ f1δi. The eyepiece converts the same d into δo ≈ d/f2, giving δo/δi ≈ f1/f2.');
    });

  var gAngles = scene.group();
  line(gAngles, 80, yLefts[0] + 36, 174, yLefts[0] + 36, blue, 2);
  curvedArrow(gAngles, 'M 119 ' + (yLefts[0] - 1) + ' C 95 ' + (yLefts[0] + 13) + ' 95 ' + (yLefts[0] + 38) + ' 117 ' + (yLefts[0] + 46), 'δi: the small incoming angle relative to the optical axis.');
  haloText(gAngles, 'δᵢ', 45, yLefts[0] + 18, 57, black, 'middle');

  line(gAngles, 80, yLefts[1] + 36, 174, yLefts[1] + 36, blue, 2);
  curvedArrow(gAngles, 'M 112 ' + (yLefts[1] + 6) + ' C 91 ' + (yLefts[1] + 18) + ' 93 ' + (yLefts[1] + 43) + ' 114 ' + (yLefts[1] + 49), 'The two incoming purple rays are parallel, so they share the same δi.');
  haloText(gAngles, 'δᵢ', 45, yLefts[1] + 28, 57, black, 'middle');

  var meanOut = (slopesOut[0] + slopesOut[1]) / 2;
  var yOutRef = axisY + meanOut * 265;
  line(gAngles, 2242, axisY, 2315, axisY, blue, 1.8).opacity(0.95);
  curvedArrow(gAngles, 'M 2277 ' + (axisY + 18) + ' C 2300 ' + (axisY + 69) + ' 2287 ' + (yOutRef + 43) + ' 2259 ' + (yOutRef + 62), 'δo: the larger outgoing angle. In the afocal case both outgoing rays have this same direction.');
  haloText(gAngles, 'δₒ', 2335, yOutRef + 34, 62, black, 'middle');

  var gBrackets = scene.group();
  drawBracket(gBrackets, x1, xF, 892, 'f₁', 'Objective focal length: distance from lens 1 to the shared focal point where the offset d is measured.', (x1 + xF) / 2, 842);
  drawBracket(gBrackets, afocalX2, xF, 776, 'f₂', 'Eyepiece focal length: in the afocal position, lens 2 is one f2 to the left of the shared focal point.', (afocalX2 + xF) / 2 + 18, 724);

  var gLabels = scene.group();
  haloText(gLabels, 'lens 1', x1 + 8, 55, 68, blue, 'middle');
  haloText(gLabels, 'lens 2', x2 + 5, 173, 68, blue, 'middle');

